public class IfElseAgeVote {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int age=18;
		if(age==18)
		{
			System.out.println("a");
		}
		if(age>18)
		{
			System.out.println("b");
		}
		else
		{
			System.out.println("c");
		}
		

	}


	}


